require_once __DIR__.'/CompanyProjectDiscussionsSchema.php';require_once __DIR__.'/CompanyProjectDiscussionExtrasSchema.php';require_once __DIR__.'/CompanyDiscussionPostProof.php';require_once __DIR__.'/CompanyProjectsSchema.php';require_once __DIR__.'/CompanyPortalOperationsSchema.php';require_once __DIR__.'/CompanyPortal.php';require_once __DIR__.'/issuers/IssuerResourceAccess.php';require_once __DIR__.'/issuers/IssuerTransaction.php';
/** Exact project/contact origins; no historical discussions or legacy IDs are adopted. */
abstract class CompanyProjectDiscussionsStorage
{
    protected ?CompanyPortal $portal=null;
    public function __construct(protected $db,protected string $p,?string $secret=null){if(!preg_match('/^[A-Za-z0-9_]+$/D',$p))throw new InvalidArgumentException('Invalid table prefix');if($secret!==null)$this->portal=new CompanyPortal($db,$p,$secret);}
    protected function rows(string $sql,array $args=[]):array{return IssuerStorage::query($this->db,$sql,$args)->result_array();}
    public function tables():array{return array_merge(['issuers_lock','issuers_registry','issuers_installation_identity','issuers_staff','issuers_resource_permissions','staff','issuers_clients','clients','contacts','contact_permissions','issuers_audit','company_projects','company_portal_projects'],array_keys(CompanyProjectDiscussionsSchema::definitions($this->p)),array_keys(CompanyProjectDiscussionExtrasSchema::definitions($this->p)));}
    protected function tx(callable $work){CompanyProjectsSchema::assertValid($this->db,$this->p);CompanyPortalOperationsSchema::assertValid($this->db,$this->p);CompanyProjectDiscussionsSchema::assertValid($this->db,$this->p);CompanyProjectDiscussionExtrasSchema::assertValid($this->db,$this->p);return IssuerTransaction::run($this->db,$this->p,$this->tables(),$work);}
    protected static function hash(array $data):string{return hash('sha256',json_encode($data,JSON_THROW_ON_ERROR));}
    protected static function revision($v,bool $zero=false):int{if((!is_int($v)&&!is_string($v))||!preg_match($zero?'/^(0|[1-9][0-9]*)$/D':'/^[1-9][0-9]*$/D',(string)$v)||(int)$v>2147483646)throw new DomainException('company_project_discussion_invalid');return (int)$v;}
    protected static function key(string $key):string{if(!preg_match('/^[a-f0-9]{64}$/D',$key))throw new DomainException('company_project_discussion_unavailable');return $key;}
    protected static function text($value,bool $subject=false):string{if(!is_string($value)||strlen($value)>($subject?764:8000)||trim($value)===''||preg_match('//u',$value)!==1||preg_match('/[\x00-\x08\x0b\x0c\x0e-\x1f\x7f]/',$value)||($subject&&preg_match('/^.{1,191}$/usD',trim($value))!==1))throw new DomainException('company_project_discussion_invalid');return trim($value);}
    protected function parent(int $issuer,int $project):array{$r=$this->rows('SELECT p.id,p.issuer_id,p.client_id,p.name,p.status,p.revision FROM '.$this->p.'company_projects p JOIN '.$this->p.'issuers_clients o ON o.client_id=p.client_id AND o.owner_issuer_id=p.issuer_id JOIN '.$this->p.'clients c ON c.userid=o.client_id AND c.active=1 WHERE p.issuer_id=? AND p.id=? FOR UPDATE',[$issuer,$project])[0]??null;if(!$r)throw new DomainException('company_project_discussion_unavailable');return $r;}
    protected function rules(int $issuer,int $project):array{$r=$this->rows('SELECT open_discussions,project_discussions,revision FROM '.$this->p.'company_project_discussion_rules WHERE issuer_id=? AND project_id=? FOR UPDATE',[$issuer,$project])[0]??['open_discussions'=>0,'project_discussions'=>0,'revision'=>0];foreach(['open_discussions','project_discussions'] as $f){if(!in_array((string)$r[$f],['0','1'],true))throw new DomainException('company_project_discussion_unavailable');$r[$f]=(int)$r[$f];}$r['revision']=self::revision($r['revision'],true);return $r;}
    protected function state(int $issuer,int $project):int{$r=$this->rows('SELECT revision FROM '.$this->p.'company_project_discussion_states WHERE issuer_id=? AND project_id=? FOR UPDATE',[$issuer,$project])[0]??null;return $r?self::revision($r['revision']):0;}
    protected function bump(int $issuer,int $project,int $revision):void{if($revision>=2147483646)throw new DomainException('company_project_discussion_limit');if($revision===0)IssuerStorage::query($this->db,'INSERT INTO '.$this->p.'company_project_discussion_states(issuer_id,project_id,revision) VALUES(?,?,1)',[$issuer,$project]);else IssuerStorage::query($this->db,'UPDATE '.$this->p.'company_project_discussion_states SET revision=revision+1 WHERE issuer_id=? AND project_id=? AND revision=?',[$issuer,$project,$revision]);if($this->state($issuer,$project)!==$revision+1)throw new RuntimeException('issuer_project_discussion_unconfirmed');}
    protected function staff(int $issuer,int $actor,int $project,string $cap='view'):array{$acl=new IssuerResourceAccess($this->db,$this->p);$acl->lockFinancialIdentity($issuer,$actor);if(!$acl->can($issuer,$actor,'projects','view')||!$acl->can($issuer,$actor,'projects',$cap))throw new DomainException('company_project_discussion_access_denied');$parent=$this->parent($issuer,$project);$person=$this->rows('SELECT firstname,lastname FROM '.$this->p.'staff WHERE staffid=? FOR UPDATE',[$actor])[0]??[];return ['parent'=>$parent,'who'=>['author_type'=>'staff','actor_id'=>$actor,'staff_id'=>$actor,'contact_id'=>null,'client_id'=>(int)$parent['client_id'],'author_name'=>trim(($person['firstname']??'').' '.($person['lastname']??''))?:'Funcionário #'.$actor]];}
    protected function contact(array $session,int $issuer,int $project,bool $writing=false,bool $opening=false):array{$who=$this->portal?->invoiceIdentity($session,$issuer,true);if(!$who||count($this->rows('SELECT id FROM '.$this->p.'contact_permissions WHERE userid=? AND permission_id=6 FOR UPDATE',[$who['contact_id']]))!==1)throw new DomainException('company_project_discussion_unavailable');$parent=$this->parent($issuer,$project);$rules=$this->rules($issuer,$project);if((int)$parent['client_id']!==$who['client_id']||!in_array($parent['status'],$writing?['active']:['active','completed','cancelled'],true)||$rules['project_discussions']!==1||($opening&&$rules['open_discussions']!==1)||!$this->rows('SELECT project_id FROM '.$this->p.'company_portal_projects WHERE issuer_id=? AND project_id=? AND visible=1 FOR UPDATE',[$issuer,$project]))throw new DomainException('company_project_discussion_unavailable');return ['parent'=>$parent,'who'=>['author_type'=>'contact','actor_id'=>$who['contact_id'],'staff_id'=>null,'contact_id'=>$who['contact_id'],'client_id'=>$who['client_id'],'author_name'=>trim($who['firstname'].' '.$who['lastname'])],'rules'=>$rules];}
    protected function source(array $r,bool $thread):array{$fields=['issuer_id','project_id','client_id','author_type','staff_id','contact_id','author_name'];if($thread)$fields[]='subject';else $fields[]='discussion_id';$fields[]='body';$fields[]='created_at';$out=[];foreach($fields as $f)$out[$f]=in_array($f,['issuer_id','project_id','client_id','staff_id','contact_id','discussion_id'],true)&&$r[$f]!==null?(int)$r[$f]:$r[$f];return $out;}
    protected function validate(array $r,bool $thread):void{if(!in_array($r['author_type']??null,['staff','contact'],true)||($r['author_type']==='contact'?($r['staff_id']!==null||!is_numeric($r['contact_id'])||(int)$r['contact_id']<1):($r['contact_id']!==null||!is_numeric($r['staff_id'])||(int)$r['staff_id']<1))||!is_string($r['author_name']??null)||preg_match('/^.{0,383}$/usD',$r['author_name'])!==1||!in_array((string)($r['active']??''),['0','1'],true))throw new RuntimeException('issuer_project_discussion_unconfirmed');try{if(self::text($r['body'])!==$r['body']||($thread&&self::text($r['subject'],true)!==$r['subject']))throw new DomainException('invalid');}catch(DomainException $bad){throw new RuntimeException('issuer_project_discussion_unconfirmed');}if(!is_string($r['content_hash']??null)||!hash_equals(self::hash($this->source($r,$thread)),$r['content_hash']))throw new RuntimeException('issuer_project_discussion_unconfirmed');if($thread){if(!in_array($r['status'],['open','closed'],true)||!in_array((string)$r['visible'],['0','1'],true))throw new RuntimeException('issuer_project_discussion_unconfirmed');self::revision($r['revision']);}elseif(!in_array($r['audience'],['private','author','public'],true))throw new RuntimeException('issuer_project_discussion_unconfirmed');if(($thread&&(int)$r['visible']===1)||(!$thread&&$r['audience']!=='private'))if(!is_string($r['published_hash'])||!hash_equals($r['content_hash'],$r['published_hash']))throw new RuntimeException('issuer_project_discussion_unconfirmed');}
    protected function thread(int $issuer,int $project,int $id,array $parent,bool $active=true):array{$r=$this->rows('SELECT * FROM '.$this->p.'company_project_discussions WHERE issuer_id=? AND project_id=? AND id=? FOR UPDATE',[$issuer,$project,$id])[0]??null;if(!$r||(int)$r['client_id']!==(int)$parent['client_id']||($active&&(string)$r['active']!=='1'))throw new DomainException('company_project_discussion_unavailable');$this->validate($r,true);return $r;}
    protected function post(int $issuer,int $project,int $thread,int $id,array $parent,bool $active=true,bool $prove=true):array{$r=$this->rows('SELECT * FROM '.$this->p.'company_project_discussion_posts WHERE issuer_id=? AND project_id=? AND discussion_id=? AND id=? FOR UPDATE',[$issuer,$project,$thread,$id])[0]??null;if(!$r||(int)$r['client_id']!==(int)$parent['client_id']||($active&&(string)$r['active']!=='1'))throw new DomainException('company_project_discussion_unavailable');$this->validate($r,false);$r['content_revision']=$prove?CompanyDiscussionPostProof::assertCurrent($this->db,$this->p,$r):CompanyDiscussionPostProof::revision($this->db,$this->p,$r);return $r;}
    protected function readable(array $thread,array $who):bool{return (int)$thread['active']===1&&((int)$thread['visible']===1||($thread['author_type']==='contact'&&(int)$thread['contact_id']===$who['contact_id']));}
    protected function postReadable(array $post,array $thread,array $who):bool{return (int)$post['active']===1&&(($post['author_type']==='contact'&&(int)$post['contact_id']===$who['contact_id'])||($post['audience']==='author'&&$thread['author_type']==='contact'&&(int)$thread['contact_id']===$who['contact_id'])||($post['audience']==='public'&&(int)$thread['visible']===1));}
    protected function audit(int $issuer,int $project,string $event,array $data,int $actor=0):void{$json=json_encode($data,JSON_THROW_ON_ERROR);IssuerStorage::query($this->db,'INSERT INTO '.$this->p.'issuers_audit(actor_id,event,issuer_id,subject_id,created_at,metadata_json) VALUES(?,?,?,?,?,?)',[$actor,$event,$issuer,$project,gmdate('Y-m-d H:i:s'),$json]);if(!$this->rows('SELECT id FROM '.$this->p.'issuers_audit WHERE id=? AND actor_id=? AND issuer_id=? AND subject_id=? AND event=? AND metadata_json=?',[(int)$this->db->insert_id(),$actor,$issuer,$project,$event,$json]))throw new RuntimeException('issuer_project_discussion_unconfirmed');}
    protected function evidence(string $kind,int $id,array $row):array{return ['kind'=>$kind,'id'=>$id,'subject'=>$kind==='thread'?$row['subject']:'','body'=>$row['body'],'author_name'=>$row['author_name'],'source_hash'=>$row['content_hash']];}
}
